package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"

	"github.com/luwa07832/shop-return-service/internal/store"
)

func newTestRouter(t *testing.T) http.Handler {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return NewRouter(st)
}

func doJSON(t *testing.T, router http.Handler, method, path, body string) *httptest.ResponseRecorder {
	t.Helper()
	var reader *bytes.Reader
	if body != "" {
		reader = bytes.NewReader([]byte(body))
	} else {
		reader = bytes.NewReader(nil)
	}
	req := httptest.NewRequest(method, path, reader)
	req.Header.Set("Content-Type", "application/json")
	rec := httptest.NewRecorder()
	router.ServeHTTP(rec, req)
	return rec
}

func decodeBody(t *testing.T, rec *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	var out map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
		t.Fatalf("decode %q: %v", rec.Body.String(), err)
	}
	return out
}

func assertErrorCode(t *testing.T, rec *httptest.ResponseRecorder, status int, code string) {
	t.Helper()
	if rec.Code != status {
		t.Fatalf("status = %d, want %d (body %s)", rec.Code, status, rec.Body.String())
	}
	body := decodeBody(t, rec)
	errObj, ok := body["error"].(map[string]any)
	if !ok {
		t.Fatalf("body missing error object: %s", rec.Body.String())
	}
	if errObj["code"] != code {
		t.Fatalf("code = %v, want %s", errObj["code"], code)
	}
	if _, exists := errObj["message"].(string); !exists {
		t.Fatalf("error message missing: %s", rec.Body.String())
	}
	if len(body) != 1 {
		t.Fatalf("error response has extra fields: %s", rec.Body.String())
	}
}

func createReturnFixture(t *testing.T, router http.Handler, body string) string {
	t.Helper()
	rec := doJSON(t, router, http.MethodPost, "/v1/returns", body)
	if rec.Code != http.StatusCreated {
		t.Fatalf("create status = %d, body %s", rec.Code, rec.Body.String())
	}
	return decodeBody(t, rec)["id"].(string)
}

const validReturnBody = `{
	"order_id":"ord_1",
	"items":[{"product_id":"p1","quantity":2},{"product_id":"p2","quantity":1}],
	"reason":"broken","evidence":["ev1","ev2"]
}`

func TestCreateReturn(t *testing.T) {
	router := newTestRouter(t)
	rec := doJSON(t, router, http.MethodPost, "/v1/returns", validReturnBody)
	if rec.Code != http.StatusCreated {
		t.Fatalf("status = %d, body %s", rec.Code, rec.Body.String())
	}
	body := decodeBody(t, rec)
	if body["status"] != "requested" {
		t.Fatalf("status = %v", body["status"])
	}
	if !strings.HasPrefix(body["id"].(string), "ret_") {
		t.Fatalf("id = %v", body["id"])
	}
	items, ok := body["items"].([]any)
	if !ok || len(items) != 2 {
		t.Fatalf("items = %v", body["items"])
	}
}

func TestCreateReturnValidation(t *testing.T) {
	router := newTestRouter(t)
	cases := map[string]string{
		"empty body":              ``,
		"not json":                `{`,
		"missing order_id":        `{"items":[{"product_id":"p1","quantity":1}]}`,
		"blank order_id":          `{"order_id":"  ","items":[{"product_id":"p1","quantity":1}]}`,
		"missing items":           `{"order_id":"o1"}`,
		"empty items":             `{"order_id":"o1","items":[]}`,
		"missing product_id":      `{"order_id":"o1","items":[{"quantity":1}]}`,
		"blank product_id":        `{"order_id":"o1","items":[{"product_id":" ","quantity":1}]}`,
		"zero quantity":           `{"order_id":"o1","items":[{"product_id":"p1","quantity":0}]}`,
		"negative quantity":       `{"order_id":"o1","items":[{"product_id":"p1","quantity":-2}]}`,
		"fractional quantity":     `{"order_id":"o1","items":[{"product_id":"p1","quantity":1.5}]}`,
